const tenantIDsByName = `-- name: TenantIDsByName :many
SELECT t.name, t.id FROM pandokos.tenant t WHERE t.name = ANY ($1::text[])
`

type TenantIDsByNameRow struct {
	Name string
	ID   string
}

// Platform scope: the group rules of the identity provider name tenants.
func (q *Queries) TenantIDsByName(ctx context.Context, names []string) ([]TenantIDsByNameRow, error) {
	rows, err := q.db.Query(ctx, tenantIDsByName, names)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TenantIDsByNameRow{}
	for rows.Next() {
		var i TenantIDsByNameRow
		if err := rows.Scan(&i.Name, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

