const userTenants = `-- name: UserTenants :many
SELECT pandokos.user_tenants($1)::text AS tenant_id
`

func (q *Queries) UserTenants(ctx context.Context, pUserID string) ([]string, error) {
	rows, err := q.db.Query(ctx, userTenants, pUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var tenant_id string
		if err := rows.Scan(&tenant_id); err != nil {
			return nil, err
		}
		items = append(items, tenant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
